"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def sortWords(wordList):
    for i in range(0, len(wordList) - 1):
        for j in range(0, len(wordList) - i - 1):
            if (wordList[j] > wordList[(j + 1)]):
                temp_var = wordList[j]
                wordList[j] = wordList[(j + 1)]
                wordList[(j + 1)] = temp_var
    return wordList
